import os
import hashlib
import json


class Config:
    """
    Configuration class for the Author Identification Stacking Ensemble.
    """

    # ==========================================
    # Global Settings
    # ==========================================
    SEED = 42
    N_FOLDS = 5

    # ==========================================
    # File Paths
    # ==========================================
    # Input Metadata (Generated by previous steps)
    TRAIN_DATA_PATH = "./metadata/train.csv"
    VAL_DATA_PATH = "./metadata/val.csv"
    TEST_DATA_PATH = "./metadata/test.csv"

    # Output Directories
    WORKING_DIR = "./working/idea_2"
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # Ensure directories exist
    os.makedirs(WORKING_DIR, exist_ok=True)
    os.makedirs(SUBMISSION_DIR, exist_ok=True)

    # ==========================================
    # Feature Extraction Configuration
    # ==========================================
    # Hybrid N-Gram settings
    WORD_NGRAM_RANGE = (1, 3)
    CHAR_NGRAM_RANGE = (2, 5)

    # Pruning
    MIN_DF = 2  # Remove terms appearing in fewer than 2 documents

    # Dimensionality Reduction (for Tree-based models)
    SVD_N_COMPONENTS = 300
    SVD_RANDOM_STATE = SEED

    # ==========================================
    # Model Hyperparameters
    # ==========================================
    # 1. Logistic Regression (Base Estimator)
    LR_PARAMS = {
        "C": 1.0,
        "solver": "saga",
        "multi_class": "multinomial",
        "max_iter": 1000,
        "random_state": SEED,
        "n_jobs": -1,
    }

    # 2. Multinomial Naive Bayes (Base Estimator)
    MNB_PARAMS = {"alpha": 0.1, "fit_prior": True}  # Smoothing parameter

    # 3. XGBoost (Base Estimator - operates on SVD features)
    XGB_PARAMS = {
        "n_estimators": 200,
        "max_depth": 6,
        "learning_rate": 0.1,
        "objective": "multi:softprob",
        "num_class": 3,
        "subsample": 0.8,
        "colsample_bytree": 0.8,
        "n_jobs": -1,
        "random_state": SEED,
        "verbosity": 0,
    }

    # 4. Meta-Learner (Logistic Regression)
    META_LR_PARAMS = {
        "C": 1.0,
        "solver": "lbfgs",
        "multi_class": "multinomial",
        "random_state": SEED,
    }

    @classmethod
    def get_config_hash(cls):
        """
        Generates a deterministic MD5 hash of the current configuration.
        This hash is used to version cache files. If any parameter changes,
        the hash changes, invalidating old cache files.
        """
        config_dict = {
            "seed": cls.SEED,
            "n_folds": cls.N_FOLDS,
            "word_ngram_range": cls.WORD_NGRAM_RANGE,
            "char_ngram_range": cls.CHAR_NGRAM_RANGE,
            "min_df": cls.MIN_DF,
            "svd_n_components": cls.SVD_N_COMPONENTS,
            "lr_params": cls.LR_PARAMS,
            "mnb_params": cls.MNB_PARAMS,
            "xgb_params": cls.XGB_PARAMS,
            "meta_lr_params": cls.META_LR_PARAMS,
        }

        # Serialize to JSON with sorted keys to ensure determinism
        config_str = json.dumps(config_dict, sort_keys=True)

        # Compute MD5 hash
        return hashlib.md5(config_str.encode("utf-8")).hexdigest()

    @classmethod
    def get_cache_path(cls, filename_prefix):
        """
        Helper to generate a full path for a cached file including the config hash.
        Example: ./working/idea_2/train_features_<hash>.npz
        """
        config_hash = cls.get_config_hash()
        filename = f"{filename_prefix}_{config_hash}"
        return os.path.join(cls.WORKING_DIR, filename)
